def find_middle(s):
    if not isinstance(s, str):
        return -1

    digits = [int(c) for c in s if c.isdigit()]
    if not digits:
        return -1

    product = 1
    for d in digits:
        product *= d

    str_product = str(product)
    length = len(str_product)

    if length % 2 == 1:
        return int(str_product[length // 2])
